import {costComparison} from './cost-model.js?v=0.20.0';
import {scheduledStats,taskLabels} from './domain.js?v=0.20.0';
export const BUSINESS_DEFAULTS={avoidablePercent:0,replacementHours:0,replacementWage:21.30,appCost:0,entryScenario:false,beforeSeconds:90,afterSeconds:30};
export function validateBusinessInputs(raw={}){const a={...BUSINESS_DEFAULTS,...raw};a.entryScenario=raw.entryScenario===true||raw.entryScenario==='on';for(const k of Object.keys(BUSINESS_DEFAULTS).filter(k=>k!=='entryScenario')){a[k]=Number(a[k]);if(!Number.isFinite(a[k])||a[k]<0)throw Error('Use non-negative numbers for business assumptions.');}if(a.avoidablePercent>100||a.replacementHours>10000||a.replacementWage>500||a.appCost>100000||a.beforeSeconds>3600||a.afterSeconds>3600)throw Error('A business assumption is outside its supported range.');return a;}
export function businessFromCosts(cost,raw={}){const a=validateBusinessInputs(raw),avoidableWages=cost.wages*a.avoidablePercent/100,replacementCost=a.replacementHours*a.replacementWage,extraInhouse=cost.mileage+avoidableWages+a.appCost,net=platform=>cost.coverageComplete?platform+replacementCost-extraInhouse:null;let running={dd:0,uber:0};const cumulative=cost.rows.map(r=>{const extras=(replacementCost-a.appCost)/(cost.rows.length||1),avoidable=r.wages*a.avoidablePercent/100;running.dd+=r.ddCommission+r.ddEquipment-r.mileage-avoidable+extras;running.uber+=r.uberCommission+r.uberEquipment-r.mileage-avoidable+extras;return {date:r.date,...running};});return {assumptions:a,avoidableWages,replacementCost,extraInhouse,ddFees:cost.dd-cost.ddEquipment,uberFees:cost.uber-cost.uberEquipment,ddNet:net(cost.dd),uberNet:net(cost.uber),ddFirstPeriodNet:net(cost.dd),uberFirstPeriodNet:net(cost.uberFirstPeriod),cumulative,entryMinutes:a.entryScenario&&cost.orders?(a.beforeSeconds-a.afterSeconds)*cost.orders/60:null,roles:[0,50,100].map(percent=>({percent,dd:cost.coverageComplete?cost.dd+replacementCost-cost.mileage-cost.wages*percent/100-a.appCost:null,uber:cost.coverageComplete?cost.uber+replacementCost-cost.mileage-cost.wages*percent/100-a.appCost:null}))};}
export function businessValue(state,shifts,costInputs,raw={}){const cost=costComparison(state,shifts,costInputs),business=businessFromCosts(cost,raw),ids=new Set(cost.rows.map(r=>r.shiftId)),done=state.deliveries.filter(d=>ids.has(d.shiftId)&&d.status==='delivered'),groups=new Map();for(const d of done){const run=state.runs.filter(r=>r.shiftId===d.shiftId&&r.deliveryIds.includes(d.id)&&Date.parse(r.startedAt)<=Date.parse(d.completedAt)).sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt))[0];if(run){const list=groups.get(run.id)||[];list.push(d.id);groups.set(run.id,list);}}const batches=[...groups.values()].filter(g=>g.length>1),cold=done.filter(d=>d.hasColdItems);return {cost,business,evidence:{batchOrders:batches.reduce((n,g)=>n+g.length,0),batchTrips:batches.length,groupedTrips:batches.reduce((n,g)=>n+g.length-1,0),scheduled:scheduledStats(done),tasks:shifts.filter(s=>ids.has(s.id)).reduce((n,s)=>n+taskLabels(s.tasks||{}).length,0),coldConfirmed:cold.filter(d=>d.coldItemsConfirmedAt).length,coldOrders:cold.length}};}
